              }}
            >
              <div className="bg-emerald-500 text-white p-4 rounded-full shadow-lg transform scale-125">
                <Check size={48} />
              </div>
            </div>

            {/* Overlay Indicator - Right (Don't Know / Red) */}
            <div
              className={`absolute inset-0 z-10 pointer-events-none rounded-[2.5rem] transition-opacity duration-200 flex items-center justify-center`}
              style={{
                backgroundColor: 'rgba(244, 63, 94, 0.2)',
                opacity: swipeDelta.x < -20 ? Math.min(Math.abs(swipeDelta.x) / 200, 0.8) : 0
              }}
            >
              <div className="bg-rose-500 text-white p-4 rounded-full shadow-lg transform scale-125">
                <X size={48} />
              </div>
            </div>

            <div
              key={currentWordIndex}
              className={`absolute inset-0 ${cardBg} ${isDark ? 'shadow-black/50' : 'shadow-blue-900/10'} rounded-[2.5rem] shadow-2xl border p-7 flex flex-col origin-center overflow-hidden animate-fade-in select-none ${!isDragging ? 'transition-all duration-700' : ''}`}
              onTouchStart={onTouchStart}
              onTouchMove={onTouchMove}
              onTouchEnd={onTouchEnd}
              onMouseDown={onMouseDown}
              style={{
                touchAction: (showWriting || showAi || showForms) ? 'auto' : 'none',
                transform: swipeDirection === 'left' ? 'translate3d(-150%, 0, 0) rotate(-25deg)' :
                  swipeDirection === 'right' ? 'translate3d(150%, 0, 0) rotate(25deg)' :
                    isDragging ? `translate3d(${-swipeDelta.x}px, ${-swipeDelta.y * 0.1}px, 0) rotate(${(-swipeDelta.x / 10) * (dragStartPos.isTop ? 1 : -1)}deg)` :
                      'translate3d(0, 0, 0) rotate(0deg)',
                opacity: swipeDirection ? 0 : 1,
                cursor: isDragging ? 'grabbing' : 'grab',
                zIndex: isDragging ? 20 : 1,
                transitionTimingFunction: swipeDirection ? 'cubic-bezier(0.23, 1, 0.32, 1)' : 'cubic-bezier(0.175, 0.885, 0.32, 1.1)',
                boxShadow: isDragging ? (
                  swipeDelta.x > 30 ? `0 0 50px rgba(16, 185, 129, ${Math.min(swipeDelta.x / 150, 0.6)})` :
                    swipeDelta.x < -30 ? `0 0 50px rgba(244, 63, 94, ${Math.min(Math.abs(swipeDelta.x) / 150, 0.6)})` :
                      undefined
                ) : undefined
              }}
              onClick={(e) => e.stopPropagation()}
            >
              {renderCardContentWrapper(currentWord, isSaved)}
            </div>
          </div>
        )}

        {!isDeckFinished && (
          <div className={`w-full max-w-sm mt-8 flex justify-between px-6 transition-opacity duration-300 ${!isRevealed ? 'opacity-50' : 'opacity-100'}`}>
            <button
              onClick={() => handleSwipe('left')}
              className={`flex flex-col items-center gap-2 transition-all duration-200 group ${swipeDelta.x > minSwipeDistance ? 'scale-125' : 'hover:scale-110'}`}
            >
              <div className={`w-16 h-16 rounded-full border-2 flex items-center justify-center text-emerald-500 shadow-lg transition-all ${swipeDelta.x > minSwipeDistance ? 'bg-emerald-500 text-white border-emerald-400' : (isDark ? 'bg-slate-800 border-emerald-900 group-hover:bg-emerald-900' : 'bg-white border-emerald-100 group-hover:bg-emerald-50')}`}>
                <Check size={32} />
              </div>
              <span className={`text-[10px] font-black uppercase transition-colors ${swipeDelta.x > minSwipeDistance ? 'text-emerald-500' : 'text-emerald-600'}`}>
                {t.iKnow}
              </span>
            </button>
            <button
              onClick={() => handleSwipe('right')}
              className={`flex flex-col items-center gap-2 transition-all duration-200 group ${swipeDelta.x < -minSwipeDistance ? 'scale-125' : 'hover:scale-110'}`}
            >
              <div className={`w-16 h-16 rounded-full border-2 flex items-center justify-center text-rose-500 shadow-lg transition-all ${swipeDelta.x < -minSwipeDistance ? 'bg-rose-500 text-white border-rose-400' : (isDark ? 'bg-slate-800 border-rose-900 group-hover:bg-rose-900' : 'bg-white border-rose-100 group-hover:bg-rose-50')}`}>
                <X size={32} />
              </div>
              <span className={`text-[10px] font-black uppercase transition-colors ${swipeDelta.x < -minSwipeDistance ? 'text-rose-500' : 'text-rose-600'}`}>
                {t.dontKnow}
              </span>
            </button>
          </div>
        )}
      </div>

      <footer className="w-full max-w-sm py-4 flex flex-col items-center gap-2 opacity-60">
        <div className="flex gap-6">
          <a href="https://www.instagram.com/ferhat_hoca_ingilizce/" target="_blank" rel="noreferrer" className="flex items-center gap-1.5 text-[10px] font-bold"><Instagram size={12} /> instagram</a>
          <a href="https://ferhathocaingilizce.com" target="_blank" rel="noreferrer" className="flex items-center gap-1.5 text-[10px] font-bold"><Globe size={12} /> ferhathocaingilizce.com</a>
        </div>
      </footer>
    </div>
  );
}

export const safeJsonParse = (text) => {
    try {
        return JSON.parse(text);
    } catch (e) {
        try {
            const cleaned = text.replace(/^```(json)?|```$/gi, '').trim();
            return JSON.parse(cleaned);
        } catch {
            console.error("JSON Parse Error:", text);
            throw new Error("Invalid format");
        }
    }
};

export const calculateAdvancedSM2 = (word, quality, mode, simulatedNow) => {
    let { rep, int, ef, totalReviews, correctReviews } = word.sm2;

    totalReviews += 1;
    if (quality >= 3) correctReviews += 1;

    const modeMultiplier = {
        'recognition': 0.8,
        'recall': 1.2,
        'perfect': 1.5,
        'production': 1.5
    }[mode] || 1.0;

    if (quality >= 3) {
        if (rep === 0) {
            int = 1 * modeMultiplier;
        } else if (rep === 1) {
            int = 6 * modeMultiplier;
        } else {
            int = Math.round(int * ef * modeMultiplier);
        }
        rep += 1;
    } else {
        rep = 0;
        int = 1;
    }

    ef = ef + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02));
    if (ef < 1.3) ef = 1.3;

    const safeInt = Math.max(1, Math.round(int));
    const nextDate = simulatedNow + safeInt * 24 * 60 * 60 * 1000;

    return { ...word, sm2: { rep, int: safeInt, ef, nextDate, totalReviews, correctReviews, lastQualityScore: quality } };
};
